Boolean obd_can_rx_intake_temp (Obd_Can_Rx_Msg * obd_can_rx_msg)
{
  #define DATA(z) obd_can_rx_msg->data[z]

  #if STATUS_TEMPERATURE_ENABLE == 1
	  
	    temperature.in     = DATA(1) ; 
	    temperature.in_ena = TRUE ;   // updated intake temp
	  
  #endif

#if DBG_OBD_CAN == 1
  dbg_tx_text("*** obd_can_rx_intake_temp = ");
  dbg_tx_h8(temperature.in);
  dbg_tx_text("\r\n");
#endif

  return TRUE ;

  #undef DATA
}


